<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_role('admin');
$search = trim((string)($_GET['q'] ?? '')); $query = "SELECT u.id, u.first_name, u.last_name, u.email, u.status, p.total_xp, p.level, p.current_streak, COUNT(DISTINCT e.id) AS course_count FROM users u LEFT JOIN student_profiles p ON p.user_id = u.id LEFT JOIN enrollments e ON e.user_id = u.id WHERE u.role = 'student'"; $params = [];
if ($search !== '') { $query .= ' AND (u.first_name LIKE :search OR u.last_name LIKE :search OR u.email LIKE :search)'; $params['search'] = '%' . $search . '%'; }
$query .= ' GROUP BY u.id, u.first_name, u.last_name, u.email, u.status, p.total_xp, p.level, p.current_streak ORDER BY u.created_at DESC'; $statement = db()->prepare($query); $statement->execute($params); $students = $statement->fetchAll();
$pageTitle = 'Manage students'; require __DIR__ . '/../includes/header.php';
?>
<div class="py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 fw-bold">Students</h1><p class="text-secondary">Review learner accounts and progress.</p></div><a class="btn btn-outline-primary" href="<?= e(app_url('admin/dashboard.php')) ?>">Dashboard</a></div><form class="input-group mb-4"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search name or email"><button class="btn btn-primary">Search</button></form><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th class="ps-4">Student</th><th>Status</th><th>Courses</th><th>XP</th><th>Level</th><th>Streak</th><th class="text-end pe-4">View</th></tr></thead><tbody><?php if (!$students): ?><tr><td colspan="7" class="text-center text-secondary p-4">No students found.</td></tr><?php endif; ?><?php foreach ($students as $student): ?><tr><td class="ps-4"><strong><?= e($student['first_name'] . ' ' . $student['last_name']) ?></strong><small class="d-block text-secondary"><?= e($student['email']) ?></small></td><td><?= e(ucfirst($student['status'])) ?></td><td><?= (int)$student['course_count'] ?></td><td><?= (int)$student['total_xp'] ?></td><td><?= (int)$student['level'] ?></td><td><?= (int)$student['current_streak'] ?></td><td class="text-end pe-4"><a class="btn btn-sm btn-outline-primary" href="<?= e(app_url('admin/student.php?id=' . $student['id'])) ?>">Profile</a></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php require __DIR__ . '/../includes/footer.php'; ?>
